  's6705140067_kiosk'@'localhost', 's6705140067_kiosk'@'%',
  's6705140067_intern'@'%', 's6705140067_intern'@'localhost',
  's6705140067_etl'@'localhost', 's6705140067_etl'@'%',
  's6705140067_report'@'localhost', 's6705140067_report'@'%';

